from typing import Dict

def dual_wave_reconstructor(triplet: List[int], x0: int, delta0: int, sum_x: int, depth: int) -> Dict:
    """
    Reconstructs the most likely original 4-digit symbolic byte that collapsed to the triplet,
    given phase metadata.
    """
    # Try all candidate 4-digit sequences that yield the triplet
    candidates = []
    for a in range(6):
        for b in range(6):
            for c in range(6):
                for d in range(6):
                    seq = [a, b, c, d]
                    collapse = delta_collapse(seq)
                    if len(collapse) >= 2 and collapse[1] == triplet:
                        candidates.append(seq)

    # Filter by metadata constraints
    filtered = [
        seq for seq in candidates
        if seq[0] == x0 and abs(seq[1] - seq[0]) == delta0 and sum(seq) == sum_x and len(delta_collapse(seq)) == depth + 1
    ]

    return {
        "triplet": triplet,
        "phase_tag": {
            "x0": x0,
            "Δ0": delta0,
            "∑x": sum_x,
            "depth": depth
        },
        "valid_candidates": filtered
    }

# Test it with triplet [1, 0, 0], x0 = 3, delta0 = 1, sum = 15, depth = 4
reconstruction_result = dual_wave_reconstructor(
    triplet=[1, 0, 0],
    x0=3,
    delta0=1,
    sum_x=15,
    depth=4
)

reconstruction_result

